/**
 * Minimal structured logger — designed as a stub that mirrors the API of the
 * full logger in the original DeepPlan project, so the copied provider code
 * works unchanged.
 *
 * Replace with a real implementation (file sink, ring buffer, JSONL, etc.)
 * when the consuming app needs persistent or queryable logs.
 *
 * Only `warn` is currently called from direct.ts; the other levels and the
 * `timer()` helper are kept available so future providers can use them
 * without re-stubbing.
 */

export type LogLevel = "debug" | "info" | "warn" | "error";
export type LogData = Record<string, unknown>;

export interface LogTimer {
  end(ok: boolean, extra?: LogData): void;
}

export interface Logger {
  debug(msg: string, data?: LogData): void;
  info(msg: string, data?: LogData): void;
  warn(msg: string, data?: LogData): void;
  error(msg: string, err?: unknown, data?: LogData): void;
  timer(label: string, data?: LogData): LogTimer;
}

const LEVEL_ORDER: Record<LogLevel, number> = { debug: 10, info: 20, warn: 30, error: 40 };

function envLevel(): LogLevel {
  const raw = (process.env.LOG_LEVEL || "info").toLowerCase();
  if (raw === "debug" || raw === "info" || raw === "warn" || raw === "error") return raw;
  return "info";
}

function emit(level: LogLevel, scope: string, msg: string, data?: LogData, err?: unknown): void {
  if (LEVEL_ORDER[level] < LEVEL_ORDER[envLevel()]) return;
  const ts = new Date().toISOString();
  const tail = data && Object.keys(data).length ? " " + JSON.stringify(data) : "";
  const line = `${ts} [${level}] [${scope}] ${msg}${tail}`;
  const stream = level === "error" || level === "warn" ? console.error : console.log;
  stream(line);
  if (err instanceof Error && err.stack) stream(err.stack);
}

export function createLogger(scope: string): Logger {
  return {
    debug: (msg, data) => emit("debug", scope, msg, data),
    info:  (msg, data) => emit("info",  scope, msg, data),
    warn:  (msg, data) => emit("warn",  scope, msg, data),
    error: (msg, err, data) => emit("error", scope, msg, data, err),
    timer: (label, data) => {
      const t0 = Date.now();
      emit("debug", scope, `${label} start`, data);
      return {
        end: (ok, extra) => {
          emit(ok ? "info" : "warn", scope, `${label} ${ok ? "ok" : "fail"}`, {
            ms: Date.now() - t0,
            ...data,
            ...extra,
          });
        },
      };
    },
  };
}
